const WebAppAllSizes = () => (
  <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
    {(['sm', 'md', 'lg'] as const).map((s) => (
      <div key={s} style={{ textAlign: 'center' }}>
        <Icon size={s} variant="webApp" name="search">
          <SearchIcon />
        </Icon>
        <p style={{ fontFamily: 'Arial', fontSize: 11, color: '#7A7870', marginTop: 4 }}>{s}</p>
      </div>
    ))}
  </div>
);

const IllustrativeColours = () => (
  <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
    {[
      { colour: '#E60000', label: 'UBS Red' },
      { colour: '#BD000C', label: 'Bordeaux I' },
      { colour: '#B98E2C', label: 'Bronze I' },
      { colour: '#2E476B', label: 'Plum 90' },
    ].map(({ colour, label }) => (
      <div key={label} style={{ textAlign: 'center' }}>
        <Icon size="lg" variant="illustrative" colour={colour} name="chart">
          <ChartIcon />
        </Icon>
        <p style={{ fontFamily: 'Arial', fontSize: 11, color: '#7A7870', marginTop: 4 }}>{label}</p>
      </div>
    ))}
  </div>
);

const AllFormats = () => {
  const formats: ImpulseFormat[] = ['A0', 'A1', 'A2', 'A3', 'A4', 'A5', 'A6', 'A7', 'A8'];
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      {formats.map((f) => (
        <div key={f}>
          <Typography variant="captions" colour="#7A7870" style={{ marginBottom: 4 }}>
            Format {f}
          </Typography>
          <Impulse format={f}>
            <Typography variant="leadText2">
              The UBS impulse line scales with the ISO format.
            </Typography>
          </Impulse>
        </div>
      ))}
    </div>
  );
};

format.description:
ISO format to determine line width and spacing.
Larger formats produce a thicker impulse line.
@default 'A4'

